    /// <summary>
    /// Updates the Item Status for given record
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    /// <param name = "_itemStatus">METItemStatus enum</param>
    /// <param name = "_updateDiscontinued">true or false</param>
    private void updateItemStatus(METInventItemOrderSetup _metInventItemOrderSetup, METItemStatus _itemStatus, boolean _updateDiscontinued = false)
    {
        utcdatetime currentDateTime = DateTimeUtil::getSystemDateTime();
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = _itemStatus;

        if (_updateDiscontinued)
        {
            _metInventItemOrderSetup.DiscontinueDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(currentDateTime, DateTimeUtil::getUserPreferredTimeZone()));
        }

        _metInventItemOrderSetup.update();
    }

    /// <summary>
    /// Reprice open sales orders
    /// </summary>
    private void rePriceOpenSalesOrders()
    {
        SalesTable salesTable;
        SalesLine salesLine;
        METSalesLine metSalesLine;
        InventDim inventDim;
        EcoResProductUnitConverter productUnitConverter;
        UnitOfMeasure unitOfMeasureFrom;
        UnitOfMeasure unitOfMeasureTo;
        UnitOfMeasureConversion unitOfMeasureConversionDirect;   
        
        InventTable inventTable;
        EcoResProduct ecoResProduct;
        InventTableModule inventTableModuleOldPack;
        real factorA, factorB, convertedValue;

        inventDim.clear();
        inventDim.InventSiteId = metInventItemOrderSetupOrigItem.SiteId;
        inventDim = InventDim::findDim(inventDim);
    
        try
        {
            while select RecId from salesTable
                where salesTable.SalesStatus == SalesStatus::Backorder
                    && salesTable.DocumentStatus == DocumentStatus::Confirmation    
                join forupdate salesLine
                    where salesLine.SalesId == salesTable.SalesId
                    && salesLine.ItemId == metInventItemOrderSetupOrigItem.ItemId
                    && salesLine.SalesStatus == SalesStatus::Backorder
                join RecId, ItemId from inventTable 
                    where InventTable.ItemId == SalesLine.ItemId
                join RecId from ecoResProduct
                    where ecoResProduct.RecId == inventTable.Product
                join RecId from metSalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                    && metSalesLine.OrderExtractStatus == METOrderExtractStatus::Open
            {
                //Calculate Factor-A - Old unit to Sales Unit
                inventTableModuleOldPack = InventTableModule::find(inventTable.ItemId, ModuleInventPurchSales::Invent);
                unitOfMeasureTo = UnitOfMeasure::findBySymbol(inventTableModuleOldPack.UnitId);
                unitOfMeasureFrom = UnitOfMeasure::findBySymbol(salesLine.SalesUnit);

                productUnitConverter = EcoResProductUnitConverter::newForDistinctProduct(ecoResProduct.RecId, unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No);

                factorA = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                inventTable.ItemId,
                                salesLine.InventDimId,
                                salesLine.SalesQty,
                                salesLine.SalesUnit,
                                inventTableModuleOldPack.UnitId,
                                NoYes::Yes);

                //Calculate Factor-B 
                select firstonly Product
                    from inventTable
                    where inventTable.ItemId == metInventItemOrderSetupTempItem.ItemId;
                   
                unitOfMeasureFrom = UnitOfMeasure::findBySymbol(inventTable.inventItemSalesSetup(inventDim.inventdimId).METSalesUnit);

                productUnitConverter = EcoResProductUnitConverter::newForDistinctProduct(inventTable.Product, unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No);
                
                factorB = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                inventTable.ItemId,
                                salesLine.InventDimId,
                                salesLine.SalesQty,
                                inventTable.inventItemSalesSetup(inventDim.inventdimId).METSalesUnit,
                                inventTableModuleOldPack.UnitId,
                                NoYes::Yes);             
                
                if (factorB != 0)
                { 
                    ttsbegin;
                    unitOfMeasureConversionDirect = UnitOfMeasureConversion::findByConversion(unitOfMeasureTo.RecId, unitOfMeasureFrom.RecId);
                    convertedValue = this.roundValue(factorA / factorB, unitOfMeasureTo, unitOfMeasureConversionDirect.Rounding);
                    salesLine.SalesUnit = unitOfMeasureFrom.Symbol;
                    salesline.SalesQty = convertedValue;
                    salesLine.update();
                    ttscommit;
                }                
            }
        }
        catch(Exception::Error)
        {
            throw Error("@SYS65081");
        }
    }

    /// <summary>
    /// Process NDC dependent sites
    /// </summary>
    private void processNDCDependentSites()
    {
        ReqItemTable reqItemTable;
        InventDim inventDim;
        InventLocation inventLocation;
        InventSite inventSite;
        InventSiteId siteId = metInventItemOrderSetupOrigItem.SiteId;

        while select firstonly RecId from reqItemTable
                where reqItemTable.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && reqItemTable.ReqPOType == ReqPOType::Transfer
            join inventLocation
                where inventLocation.InventLocationId == reqItemTable.InventLocationIdReqMain
                && inventLocation.METNDCWarehouse == NoYes::Yes
            join inventDim
                where inventDim.inventDimId == reqItemTable.CovInventDimId
            exists join inventSite
                where inventDim.InventSiteId == inventSite.SiteId
                && inventSite.METNDCSite == NoYes::Yes
        {
            ItemId mainItem = metInventItemOrderSetupOrigItem.ItemId;
            ItemId tmpItem = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, inventDim.InventSiteId).TempItemPackChg;

            if(tmpItem)
            {       

                METItemPackChangeHelper metItemPackChangeHelperDependentSites = new METItemPackChangeHelper();

                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetup(METInventItemOrderSetup::findByItemAndSite(mainItem, inventDim.InventSiteId));
                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetupTempItem(METInventItemOrderSetup::findByItemAndSite(tmpItem, inventDim.InventSiteId));

                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupOrigItem(InventItemPurchSetup::find(metInventItemOrderSetupOrigItem.ItemId, inventDim.inventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupTempItem(InventItemPurchSetup::find(tmpItem, inventDim.inventDimId));

                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupOrigItem(InventItemSalesSetup::find(metInventItemOrderSetupOrigItem.ItemId, inventDim.inventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupTempItem(InventItemSalesSetup::find(tmpItem, inventDim.inventDimId));

                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMOrigItem(METItemPackChangeHelper::getWhsPhysDimOUM(metInventItemOrderSetupOrigItem.ItemId));
                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMTempItem(METItemPackChangeHelper::getWhsPhysDimOUM(tmpItem));

                metItemPackChangeHelperDependentSites.startOperation_DependentSites();
                
            }
        }
    }

    /// <summary>
    /// Process CDS Dependent Sites
    /// </summary>
    private void processCDSDependentSites()
    {
        ReqItemTable reqItemTable;
        InventDim inventDim;
        InventLocation inventLocation;
        InventSite inventSite;
        InventSiteId siteId = metInventItemOrderSetupOrigItem.SiteId;

        while select firstonly RecId from reqItemTable
                where reqItemTable.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && reqItemTable.ReqPOType == ReqPOType::Transfer
            join inventLocation
            where inventLocation.InventLocationIdReqMain == reqItemTable.InventLocationIdReqMain
            && inventLocation.METCSDWarehouse == NoYes::Yes
            && inventLocation.InventSiteId == siteId
            exists join inventDim
            where inventDim.inventDimId == reqItemTable.CovInventDimId
            exists join inventSite
            where inventDim.InventSiteId == inventSite.SiteId
            && inventSite.METNDCSite == NoYes::Yes
        {
            if(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, inventDim.InventSiteId).TempItemPackChg)
            {
                metInventItemOrderSetupOrigItem      = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, inventDim.InventSiteId);
                metInventItemOrderSetupTempItem      = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.TempItemPackChg, inventDim.InventSiteId);
                InventTable inventTable = InventTable::find(metInventItemOrderSetupOrigItem.ItemId);
                inventItemPurchSetupOrigItem = InventItemPurchSetup::find(metInventItemOrderSetupOrigItem.ItemId, inventDim.inventDimId);
                inventItemPurchSetupTempItem = InventItemPurchSetup::find(metInventItemOrderSetupOrigItem.TempItemPackChg, inventDim.inventDimId);
                inventItemSalesSetupOrigItem = InventItemSalesSetup::find(metInventItemOrderSetupOrigItem.ItemId, inventDim.inventDimId);
                inventItemSalesSetupTempItem = InventItemSalesSetup::find(metInventItemOrderSetupOrigItem.TempItemPackChg, inventDim.inventDimId);
            
                whsPhysDimUOMOrigItem = METItemPackChangeHelper::getWhsPhysDimOUM(inventTable.ItemId);
               
                whsPhysDimUOMTempItem = METItemPackChangeHelper::getWhsPhysDimOUM(metInventItemOrderSetupOrigItem.TempItemPackChg);

                this.startOperation_DependentSites();
            }
        }
    }

