    /// <summary>
    /// Gets the Item code table buffer
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventDim">Invent Dim</param>
    /// <param name = "_inventUnit">Unit Id</param>
    /// <returns></returns>
    public static ItemBarCode getInventItembarcode(ItemId _itemId, InventDim _inventDim, InventUnitId _inventUnit)
    {
        ReqItemTable reqItemTable;
        InventDim inventDim;
        InventItemBarcode inventItembarcode;

        select firstonly Recid, VendId from reqItemTable
             exists join inventDim
            where reqItemTable.ItemId == _itemId
            && reqItemTable.CovInventDimId == inventDim.inventDimId
            && inventDim.InventSiteId == _inventDim.InventSiteId
            && reqItemTable.VendId != '';

        if(!reqItemTable)
        {
            return '';
        }        
        else if (reqItemTable && reqItemTable.VendId)
        {
            select firstonly inventItembarcode
            where inventItembarcode.itemId == _itemId
            && inventItembarcode.METDefault == NoYes::Yes
            && inventItembarcode.METVendAccount == reqItemTable.VendId
            && inventItembarcode.UnitID == _inventUnit;
        }

        return inventItembarcode.itemBarCode;
    }

    /// <summary>
    /// Get vendor List price
    /// </summary>
    /// <param name = "_itemId"></param>
    /// <param name = "_inventDim"></param>
    /// <returns></returns>
    public static GUPVendPriceAmount getVendorListPrice(ItemId _itemId, InventDim _inventDim)
    {
        ReqItemTable    reqItemTable;
        InventDim       inventDim, inventDimPrice;
        InventLocation  inventLocation;
        GUPVendPriceAdmTrans gupVendPriceAdmTrans;
        GUPVendPriceAmount amount;
        GUPVendPriceJournalNum journalNum;

        select firstonly RecId, VendId from reqItemTable
                join InventLocationId from inventDim
                    where inventDim.inventDimId == reqItemTable.CovInventDimId 
                    && inventDim.InventSiteId == _inventDim.InventSiteId
                    && reqItemTable.ItemId == _itemId;
        if(reqItemTable && !InventLocation::find(inventDim.InventLocationId).METNDCWarehouse)
        {
            journalNum = reqItemTable.VendId + '-' + inventDim.InventLocationId; 

            select firstonly Amount from gupVendPriceAdmTrans
                order by gupVendPriceAdmTrans.LineNum desc
                where gupVendPriceAdmTrans.JournalNum == journalNum
                && gupVendPriceAdmTrans.ItemNum == _itemId
                exists join inventDimPrice
                where inventDimPrice.inventDimId == gupVendPriceAdmTrans.InventDimId
                && inventDimPrice.InventLocationId == inventDim.InventLocationId
                && inventDimPrice.InventSiteId == _inventDim.InventSiteId;

            amount = gupVendPriceAdmTrans.Amount;
            
        } 
        else if(reqItemTable && InventLocation::find(inventDim.InventLocationId).METNDCWarehouse)
        {
            inventDim.clear();

            select firstonly RecId, VendId from reqItemTable
                exists join inventDim
                    where inventDim.inventDimId == reqItemTable.CovInventDimId
                    && inventDim.InventSiteId == _inventDim.InventSiteId
                    && reqItemTable.ItemId == _itemId
                    join RecId, InventLocationId from inventLocation
                    where inventLocation.InventLocationId == inventDim.InventLocationId
                    && inventLocation.METNDCWarehouse == NoYes::Yes
                    && reqItemTable.ReqPOType == ReqPOType::Purch;

            journalNum = reqItemTable.VendId + '-' + inventLocation.InventLocationId;  
        
            select firstonly Amount from gupVendPriceAdmTrans
                order by gupVendPriceAdmTrans.LineNum desc
                where gupVendPriceAdmTrans.JournalNum == journalNum
                && gupVendPriceAdmTrans.ItemNum == _itemId
                exists join inventDimPrice
                where inventDimPrice.inventDimId == gupVendPriceAdmTrans.InventDimId
                && inventDimPrice.InventLocationId == inventLocation.InventLocationId
                && inventDimPrice.InventSiteId == _inventDim.InventSiteId;

            amount = gupVendPriceAdmTrans.Amount;

        }        
        
        return amount;
        
    }

